<?php use App\Support\App;$u=App::requireAuth();$q=App::db()->prepare('SELECT * FROM deposits WHERE user_id=? ORDER BY id DESC LIMIT 300');$q->execute([$u['id']]);$rows=$q->fetchAll();$title='Deposit History';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><div class="flex flex-col sm:flex-row justify-between sm:items-end gap-3"><div><h1 class="page-title">Deposit history</h1><p class="page-sub">Riwayat seluruh penambahan saldo akun Anda.</p></div><a href="/deposit" class="btn btn-dark"><i data-lucide="plus"></i>Add balance</a></div><div class="saas-card mt-6 overflow-auto"><table class="w-full text-sm min-w-[820px]"><thead><tr><th>Deposit</th><th>Method</th><th>Amount</th><th>Status</th><th>Reference</th><th>Expired</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="border-t" style="border-color:var(--line)"><td class="font-semibold"><?=htmlspecialchars($r['deposit_number'])?></td><td><span class="badge"><?=htmlspecialchars(strtoupper($r['gateway']))?></span></td><td class="font-semibold">Rp<?=number_format($r['amount'],0,',','.')?></td><td><span class="badge"><?=htmlspecialchars(strtoupper($r['status']))?></span></td><td><?=htmlspecialchars($r['provider_reference']??'-')?></td><td><?=htmlspecialchars($r['expires_at']??'-')?></td><td><?=htmlspecialchars($r['created_at'])?></td></tr><?php endforeach?></tbody></table><?php if(!$rows):?><div class="p-10 text-center"><div class="font-semibold">Belum ada deposit</div><p class="text-sm text-zinc-500 mt-1">Deposit yang dibuat akan tampil di sini.</p></div><?php endif?></div><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>